CREATE TEMP TABLE demo_contexto(fecha date) ON COMMIT DROP;
-- Estadísticas sintéticas descargadas de Mockaroo. Sin identificadores ni datos de clientes.
-- 10 anuncios x 10 días x 9 países. Importes simulados en PEN.
CREATE TEMP TABLE demo_estadisticas(lote int,dia int,pais text,impresiones bigint,clics bigint,conversiones bigint,inversion numeric,ingresos numeric,PRIMARY KEY(lote,dia,pais)) ON COMMIT DROP;

